package org.example.backend.service;
import org.example.backend.entity.UsageRecordEntity;
import org.example.backend.mapper.UsageRecordMapper;
import org.example.backend.service.impl.UsageRecordServiceImpl;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ReadModelBehaviorTest {
    @Test void teachingScheduleSearchTrimsFiltersClampsLimitAndReturnsImmutableResults(){TeachingScheduleReadService read=mock(TeachingScheduleReadService.class);TeachingScheduleQuery query=new DefaultTeachingScheduleQuery(read);when(read.search(any())).thenReturn(null);assertEquals(List.of(),query.search(new ScheduleSearchCriteria(" 2026秋 "," 教师甲 "," ",null," 数据库 "," 查找 ",3,99999)));verify(read).search(new ScheduleSearchCriteria("2026秋","教师甲",null,null,"数据库","查找",3,5000));query.search(new ScheduleSearchCriteria(null,null,null,null,null,null,null,0));verify(read).search(new ScheduleSearchCriteria(null,null,null,null,null,null,null,500));when(read.listSemesters()).thenReturn(new ArrayList<>(List.of("2026秋")));List<String> semesters=query.listSemesters();assertThrows(UnsupportedOperationException.class,()->semesters.add("2026春"));}
    @Test void teachingSummaryDefaultsMissingCountsButRetainsSemesterOptions(){TeachingScheduleReadService read=mock(TeachingScheduleReadService.class);TeachingScheduleQuery query=new DefaultTeachingScheduleQuery(read);when(read.listSemesters()).thenReturn(List.of("2026秋"));assertEquals(0,query.summary().total());assertEquals(List.of("2026秋"),query.summary().semesters());LocalDateTime updated=LocalDateTime.of(2026,10,18,10,0);when(read.summary()).thenReturn(new ScheduleSummaryData(10,2,3,4,updated));assertEquals(new ScheduleSummaryView(10,2,3,4,updated,List.of("2026秋")),query.summary());when(read.listSemesters()).thenReturn(null);assertEquals(List.of(),query.listSemesters());}
    @Test void labAvailabilityRequiresEligibleStatusAndSufficientCapacity(){LabRecordReadService read=mock(LabRecordReadService.class);LabAvailabilityQuery query=new DefaultLabAvailabilityQuery(read);Instant start=Instant.parse("2027-01-04T00:00:00Z"),end=start.plusSeconds(3600);assertFalse(query.check(1L,20,start,end).value().available());for(String status:List.of("开放","预约中","使用中","维护中","停用","未知")){when(read.findById(1,null)).thenReturn(new LabRecord(1L,"A101","机房",null,null,null,null,30,null,status,null,null,null));assertEquals(List.of("开放","预约中","使用中").contains(status),query.check(1L,20,start,end).value().available());assertFalse(query.check(1L,31,start,end).value().available());}}
    @Test void invalidAvailabilityRequestsAreRejectedBeforeQuerying(){LabRecordReadService read=mock(LabRecordReadService.class);LabAvailabilityQuery query=new DefaultLabAvailabilityQuery(read);Instant now=Instant.now();assertThrows(IllegalArgumentException.class,()->query.check(null,20,now,now.plusSeconds(1)));assertThrows(IllegalArgumentException.class,()->query.check(0L,20,now,now.plusSeconds(1)));assertThrows(IllegalArgumentException.class,()->query.check(1L,0,now,now.plusSeconds(1)));assertThrows(IllegalArgumentException.class,()->query.check(1L,1,now,now));verifyNoInteractions(read);}
    @Test void usageBatchNormalizesRecordsAndCreatesRepairsOnlyForAbnormalEntries(){UsageRecordMapper mapper=mock(UsageRecordMapper.class);BusinessLoopService loop=mock(BusinessLoopService.class);UsageRecordService service=new UsageRecordServiceImpl(mapper,loop);UsageRecordEntity normal=new UsageRecordEntity(),abnormal=new UsageRecordEntity();abnormal.setStatus("异常");when(mapper.listUsageRecords()).thenReturn(List.of(normal,abnormal));service.replaceUsageRecords(List.of(normal,abnormal));assertNotNull(normal.getUseTime());assertEquals("正常",normal.getStatus());verify(mapper).deleteAllUsageRecords();verify(mapper).insertUsageRecord(normal);verify(loop).createRepairAfterUsageAbnormal(abnormal);verify(loop,never()).createRepairAfterUsageAbnormal(normal);verify(loop).recordEvent("usage-record","batch-save","使用记录台账","已同步",Map.of("count",2));}
    @Test void emptyUsageSyncAndResetPreservePersistedLedger(){UsageRecordMapper mapper=mock(UsageRecordMapper.class);BusinessLoopService loop=mock(BusinessLoopService.class);UsageRecordService service=new UsageRecordServiceImpl(mapper,loop);when(mapper.listUsageRecords()).thenReturn(null);assertEquals(List.of(),service.replaceUsageRecords(null));assertEquals(List.of(),service.replaceUsageRecords(List.of()));assertEquals(List.of(),service.resetUsageRecords());verify(mapper,never()).deleteAllUsageRecords();}
    @Test void usageStatusUpdatesUseAuthoritativeRecordAndMissingRowsFail(){UsageRecordMapper mapper=mock(UsageRecordMapper.class);BusinessLoopService loop=mock(BusinessLoopService.class);UsageRecordService service=new UsageRecordServiceImpl(mapper,loop);UsageRecordEntity record=new UsageRecordEntity();record.setResource("A101");record.setPerson("教师甲");when(mapper.getUsageRecord(7L)).thenReturn(record);when(mapper.updateUsageRecordStatus(eq(7L),anyString())).thenReturn(1);assertSame(record,service.updateStatus(7L,"异常"));verify(loop).createRepairAfterUsageAbnormal(record);service.updateStatus(7L,"正常");verify(loop).recordEvent("usage-record","status","A101","正常",Map.of("usageRecordId",7L,"person","教师甲"));assertThrows(IllegalArgumentException.class,()->service.updateStatus(99L,"正常"));}
}
